using UnityEngine;

/// <summary>
/// Prefabs, palette materials and fonts the runtime-built escape tower can use.
/// Lives in Resources/EscapeArtSet and is (re)generated by EscapeRoomSetup (Editor).
/// </summary>
[CreateAssetMenu(menuName = "Multiverse/Escape Art Set")]
public sealed class EscapeArtSet : ScriptableObject
{
    [System.Serializable] public struct PropEntry { public string key; public GameObject prefab; }
    [System.Serializable] public struct PaintEntry { public string key; public Material material; }

    public PropEntry[] props;
    public PaintEntry[] paints;
    public Font font;
    public Material textMaterial;
    public Material characterAtlas;

    public GameObject FindPrefab(string key)
    {
        if (props != null) foreach (var p in props) if (p.key == key && p.prefab != null) return p.prefab;
        return null;
    }

    public Material FindMaterial(string key)
    {
        if (paints != null) foreach (var p in paints) if (p.key == key && p.material != null) return p.material;
        return null;
    }
}
